<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class TransportOperationsController extends Controller {
 private function school(){abort_unless(auth()->user()->school_id,403);return auth()->user()->school_id;}
 private function config($type){$all=[
 'vehicles'=>['Vehicle Management','Registration number',['model'=>'Model','capacity'=>'Seating capacity','route'=>'Route code'],['active','inactive','maintenance']],
 'staff'=>['Drivers & Attendants','Staff name',['role'=>'Driver / attendant','phone'=>'Phone','licence'=>'Licence number'],['active','inactive']],
 'trips'=>['Daily Trip Register','Trip reference',['route'=>'Route code','vehicle'=>'Vehicle registration','driver'=>'Driver','direction'=>'Pickup / drop','departure'=>'Departure time','arrival'=>'Arrival time'],['scheduled','completed','cancelled']],
 'attendance'=>['Transport Attendance','Student admission number',['route'=>'Route code','direction'=>'Pickup / drop','trip'=>'Trip reference'],['present','absent']],
 'maintenance'=>['Vehicle Maintenance','Vehicle registration',['work'=>'Work performed','vendor'=>'Vendor'],['scheduled','completed']],
 'fuel'=>['Fuel & Expense Register','Vehicle registration',['category'=>'Expense category','quantity'=>'Fuel litres','reference'=>'Invoice reference'],['recorded']],
 'documents'=>['Vehicle Documents','Document reference',['vehicle'=>'Vehicle registration','document'=>'Document type'],['active','expired']],
 'settings'=>['Transport Settings','Setting name',['value'=>'Value'],['active','inactive']]];abort_unless(isset($all[$type]),404);return $all[$type];}
 private function records($type){return DB::table('transport_operation_records')->where('school_id',$this->school())->where('type',$type);}
 public function index(Request $r,$type){$config=$this->config($type);$records=$this->records($type)->latest('id')->paginate(25);return view('transport.register',compact('config','records','type'));}
 private function payload(Request $r,$type){$c=$this->config($type);$rules=['title'=>'required|string|max:255','record_date'=>'nullable|date','expiry_date'=>'nullable|date','amount'=>'nullable|numeric|min:0|max:9999999999','status'=>'required|in:'.implode(',',$c[3])];foreach($c[2] as $k=>$label)$rules['details.'.$k]='nullable|string|max:255';if(in_array($type,['trips','attendance','fuel','maintenance']))$rules['record_date']='required|date';$v=$r->validate($rules);$v['details']=json_encode(array_intersect_key($v['details']??[],$c[2]));return $v;}
 public function store(Request $r,$type){DB::table('transport_operation_records')->insert($this->payload($r,$type)+['school_id'=>$this->school(),'type'=>$type,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Record saved.');}
 public function update(Request $r,$type,$id){abort_unless($this->records($type)->where('id',$id)->exists(),404);$this->records($type)->where('id',$id)->update($this->payload($r,$type)+['updated_at'=>now()]);return redirect()->route('transport.register',$type)->with('success','Record updated.');}
 public function dashboard(Request $r){$school=$this->school();$today=now()->toDateString();$years=DB::table('academic_years')->where('school_id',$school)->orderByDesc('start_date')->get();$year=$r->filled('academic_year_id')?$years->firstWhere('id',$r->academic_year_id):($years->first(fn($y)=>$y->start_date<=$today && $y->end_date>=$today)??$years->first());abort_unless($year,422,'Academic year not found');$assign=DB::table('student_transport_assignments')->where('school_id',$school)->where('academic_year_id',$year->id);$routes=DB::table('transport_routes')->where('school_id',$school)->orderBy('code')->get();$routeCounts=(clone $assign)->selectRaw('transport_route_id, COUNT(DISTINCT student_id) as total')->groupBy('transport_route_id')->pluck('total','transport_route_id');$dues=DB::table('student_fee_dues')->where('school_id',$school)->where('academic_year_id',$year->id)->whereNotNull('student_transport_assignment_id')->where('status',1);$cards=['Routes'=>$routes->count(),'Transport students'=>(clone $assign)->distinct()->count('student_id'),'Pickup / drop points'=>DB::table('transport_route_stops')->whereIn('transport_route_id',$routes->pluck('id'))->count(),'Active vehicles'=>$this->records('vehicles')->where('status','active')->count(),'Active staff'=>$this->records('staff')->where('status','active')->count(),'Pending fees'=>'₹ '.number_format((clone $dues)->sum('balance_amount'),2)];$trips=$this->records('trips')->whereDate('record_date',$today)->get();$alerts=$this->records('documents')->whereNotNull('expiry_date')->where('expiry_date','<=',now()->addDays(30)->toDateString())->orderBy('expiry_date')->limit(10)->get();$monthly=(clone $dues)->selectRaw('period_start, SUM(payable_amount) payable, SUM(paid_amount) paid, SUM(balance_amount) pending')->groupBy('period_start')->orderBy('period_start')->get();return view('transport.dashboard',compact('years','year','cards','routes','routeCounts','trips','alerts','monthly'));}
}
